	def closest3Sum(self, A, N, X):
		A.sort()
		min = float('inf')
		ans = 0
		for i in range(len(A)):
			j = i + 1
			k = len(A) - 1
			while j < k:
				sum = A[i] + A[j] + A[k]
				if abs(sum - X) < min:
					min = abs(sum - X)
					ans = sum
					j += 1
				elif sum < X:
					j += 1
				else:
					k -= 1
		return ans

