from collections import deque

class Solution:

	def findMax(self, root):
		max = 0
		stack = deque()
		while True:
			if root:
				if root.data > max:
					max = root.data
				stack.append(root)
				root = root.left
			else:
				if not stack:
					break
				root = stack.pop()
				root = root.right
		return max

	def findMin(self, root):
		min = 10001
		stack = deque()
		while True:
			if root:
				if root.data < min:
					min = root.data
				stack.append(root)
				root = root.left
			else:
				if not stack:
					break
				root = stack.pop()
				root = root.right
		return min

