import sys

class Tree(object):

	def left(self, index):
		return 2 * index + 1

	def get_if_present(self, idx):
		if idx < len(self.list):
			return self.list[idx]
		else:
			return None

	def lval(self, index):
		return self.get_if_present(self.left(index))

	def rval(self, index):
		return self.get_if_present(self.right(index))

	def right(self, index):
		return self.left(index) + 1

	def parent(self, index):
		return math.floor((index - 1) / 2)

	def insert(self, val):
		self.list.append(val)
		return len(self.list) - 1

	def find(self, val):
		return self.list.index(val)

	def __init__(self):
		self.list = []

def insert(tree, value):
	idx = tree.insert(value)
	while tree.list[tree.parent(idx)] > value and idx > 0:
		tree.list[idx] = tree.list[tree.parent(idx)]
		tree.list[tree.parent(idx)] = value
		idx = tree.parent(idx)

def remove(tree, value):
	idx = tree.find(value)

	def match(tv, lval, rval):
		if lval and tv > lval:
			return True
		if rval and tv > rval:
			return True
		return False
	if idx == len(tree.list) - 1:
		tree.list.pop()
		return
	tree.list[idx] = tree.list.pop()
	while match(tree.list[idx], tree.lval(idx), tree.rval(idx)):
		left = tree.left(idx)
		right = tree.right(idx)
		rv = tree.rval(idx)
		lv = tree.lval(idx)
		ov = tree.list[idx]
		if rv and ov > rv and (lv is None or lv > rv):
			tree.list[idx] = rv
			tree.list[right] = ov
			idx = right
		elif lv and ov > lv and (rv is None or rv > lv):
			tree.list[idx] = lv
			tree.list[left] = ov
			idx = left

