def mutations(alice, bob, word, first):
	(players, seen) = ([alice, bob], {word})
	(win, failed, i) = (-1, -1, first ^ 1)
	while 1:
		i ^= 1
		lst = players[i]
		reg = re.compile('|'.join(genMask(word)))
		found = next((w for w in lst if reg.match(w) and w not in seen and (len(set(w)) == 4)), None)
		if found is None:
			if failed == i ^ 1:
				break
			failed = i
		else:
			seen.add(found)
			(word, win) = (found, i)
			if failed != -1:
				break
	return win

def binarySearch(arr, number):
    left = 0
    right = len(arr) - 1
    while left <= right:
        mid = (left + right)//2
        if arr[mid] == number:
            return mid
        elif arr[mid] < number:
            left = mid + 1
        else:
            right = mid - 1
    return -1

