def factor(n):
	f = {}
	for p in primes:
		if p * p > n:
			break
		while n % p == 0:
			n //= p
			f[p] = f.get(p, 0) + 1
	if n > 1:
		f[n] = 1
	return f

def totient(n):
	f = factor(n)
	t = 1
	for p in f:
		t *= (p - 1) * p ** (f[p] - 1)
	return t
