def longestPathFrom(root, getNbr):
	queue = deque()
	queue.append(root)
	parent = {}
	parent[root] = None
	while queue:
		curr = queue.popleft()
		for child in getNbr(curr):
			if child not in parent:
				queue.append(child)
				parent[child] = curr
	ret = [curr]
	while curr in parent and parent[curr] is not None:
		curr = parent[curr]
		ret.append(curr)
	return ret[::-1]

def treeDiameter(graph):
	initNode = 0

	def getNbr(node):
		return graph[node]
	path1 = longestPathFrom(initNode, getNbr)
	assert path1[0] == initNode
	path2 = longestPathFrom(path1[-1], getNbr)
	return path2

def solve(N, edges):
	graph = [[] for i in range(N)]
	for (u, v) in edges:
		graph[u].append(v)
		graph[v].append(u)

	def getDeepest(u, exclude):
		retDepth = 0
		retChild = u
		for v in graph[u]:
			if v not in exclude:
				(childDepth, child) = getDeepest(v, [u])
				if 1 + childDepth > retDepth:
					retDepth = 1 + childDepth
					retChild = child
		return (retDepth, retChild)
	path = treeDiameter(graph)
	base = len(path) - 1
	best = (0, path[1])
	for i in range(1, len(path) - 1):
		best = max(best, getDeepest(path[i], [path[i - 1], path[i + 1]]))
	return str(base + best[0]) + '\n' + ' '.join((str(x + 1) for x in [path[0], best[1], path[-1]]))
