class Solution:

	def maximumDistance(self, v: int, e: int, src: int, edges: List[List[int]]) -> List[int]:
		n = v
		adj = dict(list)
		dist = [-float('inf') for i in range(v)]
		visited = set()
		q = dq([(src, 0)])
		topo = []

		def postDfs(node):
			for (neib, w) in adj[node]:
				if neib not in visited:
					postDfs(neib)
			visited.add(node)
			topo.append(node)
		for edge in edges:
			(u, v, w) = (edge[0], edge[1], edge[2])
			adj[u].append((v, w))
		for i in range(n):
			if i not in visited:
				postDfs(i)
		dist[src] = 0
		while topo:
			node = topo.pop(-1)
			nodeDist = dist[node]
			for (neib, w) in adj[node]:
				if dist[neib] < nodeDist + w:
					dist[neib] = nodeDist + w
		for (i, d) in enumerate(dist):
			if d == float('-inf'):
				dist[i] = 'INF'
		return dist

