import math

def is_prime(num):
    """Function to check for prime number"""
    if num == 1:
        return False

    for i in range(2, int(math.sqrt(num)) + 1):
        if num % i == 0:
            return False
    return True


def get_first_prime_numbers(limit):
    """Function to get the first limit prime numbers"""
    num = 2
    count = 0
    prime_numbers = []

    while count < limit:
        if is_prime(num):
            prime_numbers.append(num)
            count += 1
        num += 1

    return prime_numbers


