class Solution:

	def solve(self, mat, n, u, dist, kAtms):
		if kAtms == 0 or u == n:
			return max(dist)
		temp = []
		for (v, val) in enumerate(dist):
			temp.append(min(val, mat[u][v]))
		c1 = self.solve(mat, n, u + 1, temp, kAtms - 1)
		c2 = self.solve(mat, n, u + 1, dist, kAtms)
		return min(c1, c2)

	def selectKcities(self, n: int, k: int, mat: List[List[int]]) -> int:
		dist = [10000000000.0] * n
		return self.solve(mat, n, 0, dist, k)

