def Largest_Square(grid):
	h = len(grid)
	w = len(grid[0])
	dp = [[0] * w for i in range(h)]
	maxlenth = 0
	for i in range(h):
		for j in range(w):
			dp[i][j] = (grid[i][j] + 1) % 2
			maxlenth = max(maxlenth, dp[i][j])
	for i in range(1, h):
		for j in range(1, w):
			if grid[i][j]:
				continue
			else:
				dp[i][j] = min(dp[i - 1][j], dp[i - 1][j - 1], dp[i][j - 1]) + 1
				maxlenth = max(maxlenth, dp[i][j])
	return maxlenth ** 2
