class Solution:

	def numRollsToTarget(self, d: int, f: int, target: int) -> int:
		if target < d * 1 or target > d * f:
			return 0
		target = target - d
		sum = 0
		i = 0
		j = 0
		while i <= target:
			y = target - i
			if j % 2 == 0:
				sum = int(sum + comb(d, j) * comb(y + d - 1, y))
			else:
				sum = int(sum - comb(d, j) * comb(y + d - 1, y))
			j = j + 1
			i = i + f
		return int(sum) % 1000000007

