EPS = 1e-09

def line_cross_point(P1, P2, Q1, Q2):
	(x0, y0) = P1
	(x1, y1) = P2
	(x2, y2) = Q1
	(x3, y3) = Q2
	dx0 = x1 - x0
	dy0 = y1 - y0
	dx1 = x3 - x2
	dy1 = y3 - y2
	s = (y0 - y2) * dx1 - (x0 - x2) * dy1
	sm = dx0 * dy1 - dy0 * dx1
	if -EPS < sm < EPS:
		return None
	return (x0 + s * dx0 / sm, y0 + s * dy0 / sm)

def bisector(P1, P2, Q1, Q2):
	(x0, y0) = P1
	(x1, y1) = P2
	(x2, y2) = Q1
	(x3, y3) = Q2
	dx0 = x1 - x0
	dy0 = y1 - y0
	dx1 = x3 - x2
	dy1 = y3 - y2
	cp = line_cross_point(P1, P2, Q1, Q2)
	if cp is None:
		return None
	(cx, cy) = cp
	d0 = (dx0 ** 2 + dy0 ** 2) ** 0.5
	d1 = (dx1 ** 2 + dy1 ** 2) ** 0.5
	return [((cx, cy), (cx + (dx0 * d1 + dx1 * d0), cy + (dy0 * d1 + dy1 * d0))), ((cx, cy), (cx + (dx0 * d1 - dx1 * d0), cy + (dy0 * d1 - dy1 * d0)))]

def line_point_dist2(p1, p2, q):
	(x, y) = q
	(x1, y1) = p1
	(x2, y2) = p2
	dx = x2 - x1
	dy = y2 - y1
	dd = dx ** 2 + dy ** 2
	sv = (x - x1) * dy - (y - y1) * dx
	return abs(sv / dd ** 0.5)

def check(LS, q):
