class Solution:

	def rec_sol(self, a, n):
		if n <= 2:
			return 0
		return min(min(a[n - 1] + self.rec_sol(a, n - 1), a[n - 2] + self.rec_sol(a, n - 2)), a[n - 3] + self.rec_sol(a, n - 3))

	def mem_sol(self, a, n, dp):
		if n <= 2:
			return 0
		if dp[n] != -1:
			return dp[n]
		dp[n] = min(min(a[n - 1] + self.mem_sol(a, n - 1, dp), a[n - 2] + self.mem_sol(a, n - 2, dp)), a[n - 3] + self.mem_sol(a, n - 3, dp))
		return dp[n]

	def dp_sol(self, a, n):
		if n <= 2:
			return 0
		dp = [0] * (n + 1)
		dp[3] = min(min(a[0], a[1]), a[2])
		for i in range(4, n + 1):
			dp[i] = min(min(a[i - 1] + dp[i - 1], a[i - 2] + dp[i - 2]), a[i - 3] + dp[i - 3])
		return dp[n]

	def minSum(self, a, n):
		return self.dp_sol(a, n)

