def find_square0(data):
	max_size = 0
	dp = []
	for row in data:
		temp = []
		for c in row:
			if c == '.':
				temp.append(1)
			else:
				temp.append(0)
		dp.append(temp)
	for y in range(1, len(dp)):
		for x in range(1, len(dp[0])):
			if dp[y][x] == 1:
				dp[y][x] = min(dp[y - 1][x - 1], dp[y - 1][x], dp[y][x - 1]) + 1
				if dp[y][x] > max_size:
					max_size = dp[y][x]
	return max_size

def find_square2(data):
	max_size = 0
	dp = [[0] * len(data[0]) for _ in range(len(data))]
	for (y, row) in enumerate(data):
		for (x, c) in enumerate(row):
			if c == '.':
				dp[y][x] = 1
	prev_row = dp[0]
	for curr_row in dp[1:]:
		for (x, t) in enumerate(curr_row[1:], start=1):
			if t == 1:
				curr_row[x] = min(prev_row[x - 1], prev_row[x], curr_row[x - 1]) + 1
				if curr_row[x] > max_size:
					max_size = curr_row[x]
		prev_row = curr_row
	return max_size

