class Solution:

	def solve(self, M, K, bloomDay):
		if len(bloomDay) < M * K:
			return -1
		l = min(bloomDay)
		r = max(bloomDay)
		while l <= r:
			mid = (l + r) // 2
			count = 0
			bq = 0
			for i in range(len(bloomDay)):
				if count < K and bloomDay[i] > mid:
					count = 0
				if bloomDay[i] <= mid:
					count = count + 1
				if count == K:
					bq = bq + 1
					count = 0
			if bq == M:
				ans = mid
				r = mid - 1
			elif bq < M:
				l = mid + 1
			else:
				r = mid - 1
		return ans

