def int_to_binary(n):
    if n == 0:
        return '0'
    bin_string = ""
    while n > 0:
        bin_string = str(n%2) + bin_string
        n = n // 2
    return bin_string

class Solution:
    def removeZeroSumSublists(self, head: Optional[ListNode]) -> Optional[ListNode]:
        if head:
            total = 0
            curr = head
            while curr:
                total += curr.val
                if total == 0:
                    return self.removeZeroSumSublists(curr.next)
                curr = curr.next
            head.next = self.removeZeroSumSublists(head.next)
        return head

