	def Countpair(self, arr, n, sum):
		count = 0
		front = 0
		back = n - 1
		while front < n and back >= 0:
			tempsum = arr[front] + arr[back]
			if tempsum == sum:
				count += 1
				if arr[front] == arr[back]:
