def merge(x, y):
	if len(x) > len(y):
		(x, y) = (y, x)
	for i in x:
		y[i] = y[i] + x[i] if i in y else x[i]
	return (y, y)

def NC_Dij(lis, start):
	ret = [float('inf')] * len(lis)
	ret[start] = 0
	q = deque([start])
	plis = [i for i in range(len(lis))]
	while len(q) > 0:
		now = q.popleft()
		for nex in lis[now]:
			if ret[nex] > ret[now] + 1:
				ret[nex] = ret[now] + 1
				plis[nex] = now
				q.append(nex)
	return (ret, plis)
