		return dp[n]

class Solution:

	def bellNumber(self, n: int) -> int:
		m = [[0] * (n + 1) for _ in range(n + 1)]
		m[0][0] = 1
		for i in range(1, n + 1):
			m[i][0] = m[i - 1][i - 1]
			for j in range(1, i + 1):
				m[i][j] = (m[i - 1][j - 1] + m[i][j - 1]) % 1000000007
		return m[n][0]

