def amax(a):
	return max(map(abs, a))

def multiply_polynomials_kronecker_2(p1, p2, modulus):
	(c1max, c2max) = (amax(p1), amax(p2))
	cbound = c1max * c2max * len(p1) * len(p2)
	xlen = int.bit_length(cbound) + 2
	x = 1 << xlen
	x1 = x - 1

	def k(p):
		(t, s) = (1, 0)
		for c in p:
			s += t * c
			t <<= xlen
		return s
	(n1, n2) = (k(p1), k(p2))
	nprod = n1 * n2
	nstr = '{:b}'.format(nprod)[::-1]
	res = []
	for i in range(0, len(nstr), xlen):
		res.append(int(nstr[i:i + xlen][::-1], 2) % modulus)
	return res

def multiply_polynomials_kronecker(ps, modulus):
	if len(ps) == 1:
		return ps[0]
	isplit = len(ps) // 2
	p1 = multiply_polynomials_kronecker(ps[:isplit], modulus)
	p2 = multiply_polynomials_kronecker(ps[isplit:], modulus)
	return multiply_polynomials_kronecker_2(p1, p2, modulus)

def school_multiply(p, q):
	a = [0] * (len(p) + len(q) - 1)
	for (i, x) in enumerate(p):
		for (j, y) in enumerate(q):
			a[i + j] += p[i] * q[j]
	return a

def school_multiply_1cx(c1s, modulus, minDegree=None):
	deg = len(c1s)
	p = [0] * (deg + 1)
	(p[0], p[1]) = (1, c1s[0] % modulus)
	for c in c1s[1:]:
		t = p[0]
		for i in range(1, deg + 1):
			(t, p[i]) = (p[i], (p[i] + c * t) % modulus)
	if minDegree is not None:
		if len(p) < minDegree:
			p += [0] * (minDegree - len(p))
	return p

