			y += 1
		if y == Y:
			return (None, None)
		free = 0
		while mx[y] & 1 << free != 0:
			free += 1
		if free >= X:
			return (None, None)
		return (free, y)

	def place_queen(x, y, mx):
		nmx = list(mx)
		for dx in [-1, 0, 1]:
			for dy in [-1, 0, 1]:
				if dx == 0 and dy == 0:
					continue
				(cx, cy) = (x, y)
				while not is_wall(cx, cy):
					nmx[cy] |= 1 << cx
					(cx, cy) = (cx + dx, cy + dy)
		return tuple(nmx)

	@memoize
	def rec(mx):
		(free_x, free_y) = get_free(mx)
		if free_x == None:
			return 0
		imx = list(mx)
		imx[free_y] |= 1 << free_x
		ans = rec(tuple(imx))
		nmx = place_queen(free_x, free_y, mx)
		ans += 1
		(free_x, free_y) = get_free(nmx)
		if free_x != None:
			ans += rec(nmx)
		return ans % mod
