	def closestToZero(self, arr, n):
		arr.sort()
		(i, j) = (0, n - 1)
		m = arr[0] + arr[n - 1]
		while i < j:
			c = arr[i] + arr[j]
			if c == 0:
				return 0
			if c < 0:
				i += 1
			else:
				j -= 1
			if self.abs_val(c) < self.abs_val(m):
				m = c
			if self.abs_val(c) == self.abs_val(m):
				m = m if m > c else c
		return m

