class Solution:

	def nthUglyNumber(self, n: int, a: int, b: int, c: int) -> int:

		def enough(num):
			total = num // a + num // b + num // c - num // ab - num // bc - num // ac + num // abc
			return total >= n
		ab = a * b // math.gcd(a, b)
		ac = a * c // math.gcd(a, c)
		bc = b * c // math.gcd(b, c)
		abc = a * bc // math.gcd(a, bc)
