import math
import heapq
EPS = 1e-08
pp0 = [0j, 4 + 0j, 4 + 4j, 4j]

def EQ(a, b):
	return abs(a - b) < EPS

def PPeQ(a, b):
	return EQ(a.real, b.real) and EQ(a.imag, b.imag)

def dcmp(x):
	if PPeQ(x, 0):
		return 0
	return -1 if x <= 0 else 1

def cross(a, b):
	return a.real * b.imag - a.imag * b.real

def vabs(a):
	return math.hypot(a.real, a.imag)

def crossPointS2P(seg, bs, be):
	a1 = cross(be - bs, seg[0] - bs)
	a2 = cross(be - bs, seg[1] - bs)
	return complex((seg[0].real * a2 - seg[1].real * a1) / (a2 - a1), (seg[0].imag * a2 - seg[1].imag * a1) / (a2 - a1))

def bisector(a, b):
	(ax, ay) = ((a.real + b.real) / 2, (a.imag + b.imag) / 2)
	if EQ(a.imag, b.imag):
		return [complex(ax, ay), complex(ax, ay + (b.real - a.real) * 100)]
	t = ax - (b.imag - a.imag) * 100
	return [complex(ax, ay), complex(t, (ax - t) * (b.real - a.real) / (b.imag - a.imag) + ay)]

def convex_cut(seg, p):
	(ans, n) = ([], len(p))
	for i in range(n):
		d1 = dcmp(cross(seg[1] - seg[0], p[i] - seg[0]))
		t = p[0] if i + 1 == n else p[i + 1]
		d2 = dcmp(cross(seg[1] - seg[0], t - seg[0]))
		if d1 >= 0:
			ans.append(p[i])
		if d1 * d2 < 0:
			ans.append(crossPointS2P(seg, p[i], t))
	return ans

