def dijkstra(V, to, tbl):
	visited = [0] * V
	Q = []
	for i in range(V):
		if EQ(tbl[i].real, 0):
			heapq.heappush(Q, (0, i, 0))
			visited[i] = 1
	while Q:
		(t, s, x) = heapq.heappop(Q)
		if EQ(x, 4):
			return t
		for e in to[s]:
			if visited[e]:
				continue
			visited[e] = 1
			heapq.heappush(Q, (t + vabs(tbl[s] - tbl[e]), e, tbl[e].real))
	return -1
