				ae.append(a[i])
			if b[i] % 2:
				bo.append(b[i])
			else:
				be.append(b[i])
		if len(ao) != len(bo) or len(ae) != len(be):
			return -1
		(osum, esum) = (0, 0)
		for i in range(len(ao)):
			osum += abs(ao[i] - bo[i])
		for i in range(len(ae)):
			esum += abs(ae[i] - be[i])
		if osum % 2 or esum % 2:
			return -1
		else:
			return (osum + esum) // 2 // 2

