			factors.append(p)
		while n % p == 0:
			n //= p
		p += 1
	if n > 1:
		factors.append(n)
	return factors

def get_n_coprimes(n, m):
	if n == 1:
		return m
	l = len(prm_factors[n])
	ans = 0
	for i in range(1, 2 ** l):
		prod = 1
		cnt = 0
		for j in range(l):
			if 1 << j & i > 0:
				prod *= prm_factors[n][j]
				cnt += 1
		if cnt & 1 == 1:
			ans -= m // prod
		else:
			ans += m // prod
	return m + ans
