class Solution:
    def cost(self, cost, i, j, m, n, took, used):
        if i >= m:
            if used + 1 != 1 << n:
                return float('inf')
            return 0
        key = (i, j, took, used)
        if key in self.cache:
            return self.cache[key]
        res = float('inf')
        newi = i
        newj = j + 1
        if newj >= n:
            newi += 1
            newj = 0
        res = min(res, cost[i][j] + self.cost(cost, newi, newj, m, n, bool(newj != 0), used | (1 << j)))
        if j != n - 1 or took:
            res = min(res, self.cost(cost, newi, newj, m, n, bool(took and newj != 0), used))
        self.cache[key] = res
        return res

    def connectTwoGroups(self, cost: List[List[int]]) -> int:
        m = len(cost)
        n = len(cost[0])
        self.cache = {}
        return self.cost(cost, 0, 0, m, n, False, 0)

class Solution:

	def flipLights(self, n, m):
		states = set()
		for op_odd in [0, 1]:
			for op_even in [0, 1]:
				for op_third in [0, 1]:
					op_all = m - op_odd - op_even - op_third
					if op_all >= 0:
						one = (op_odd + op_all + op_third) % 2
						two = (op_even + op_all) % 2
						three = op_odd % 2
						four = (op_even + op_all + op_third) % 2
						states.add((one, two, three, four)[:n])
		return len(states)

