class Solution:

	def minDifference(self, n: int, arr: List[int]) -> List[List[int]]:
		total = sum(arr)
		s1 = s2 = 0
		min_diff = float('inf')
		for subset in combinations(arr, n // 2):
			sum1 = sum(subset)
			sum2 = total - sum1
			if sum1 > sum2:
				(sum1, sum2) = (sum2, sum1)
			diff = abs(sum2 - sum1)
			if diff < min_diff:
				min_diff = diff
				(s1, s2) = (sum1, sum2)
		return [[s1], [s2]]

def Helper(arr, n, curr_elements, no_of_selected_elements, soln, min_diff, Sum, curr_sum, curr_position):
	if curr_position == n:
		return
	if int(n / 2) - no_of_selected_elements > n - curr_position:
		return
	Helper(arr, n, curr_elements, no_of_selected_elements, soln, min_diff, Sum, curr_sum, curr_position + 1)
	no_of_selected_elements += 1
	curr_sum = curr_sum + arr[curr_position]
	curr_elements[curr_position] = True
	if no_of_selected_elements == int(n / 2):
		if abs(int(Sum / 2) - curr_sum) < min_diff[0]:
			min_diff[0] = abs(int(Sum / 2) - curr_sum)
			for i in range(n):
				soln[i] = curr_elements[i]
	else:
		Helper(arr, n, curr_elements, no_of_selected_elements, soln, min_diff, Sum, curr_sum, curr_position + 1)
	curr_elements[curr_position] = False

