        self.k = k
        self.heap = nums
        heapq.heapify(self.heap)
        while len(self.heap) > k:
            heapq.heappop(self.heap)

    def add(self, val: int) -> int:
        heapq.heappush(self.heap, val)
        if len(self.heap) > self.k:
            heapq.heappop(self.heap)
        return self.heap[0]

M = 1000003

class Solution:

	def __init__(self):
		self.f = [1] * M
		for i in range(1, M):
			self.f[i] = self.f[i - 1] * i % M

	def nCr(self, n, r):
		if r > n:
			return 0
		if r == 0:
			return 1
		if n < M and r < M:
			return self.f[n] * pow(self.f[r], M - 2, M) * pow(self.f[n - r], M - 2, M) % M
		return self.nCr(n // M, r // M) * self.nCr(n % M, r % M) % M

