		lps = [0] * len(s)
		(prevLPS, i) = (0, 1)
		while i < len(s):
			if s[prevLPS] == s[i]:
				lps[i] = prevLPS + 1
				prevLPS += 1
				i += 1
			elif prevLPS == 0:
