MOD = 10 ** 9 + 7
MODF = float(MOD)
MODF_inv = 1.0 / MODF

def modder(a):
	return a - MODF * trunc(a * MODF_inv)
SHRT = float(1 << 16)
SHRT_inv = 1.0 / SHRT

def mod_prod(a, b, c=0):
	a1 = trunc(a * SHRT_inv)
	a2 = a - SHRT * a1
	b1 = modder(b * SHRT)
	b2 = b
	return modder(a2 * b2 + a1 * b1 + c)

def mult(A, B):
	(n, m) = (len(A[0]), len(B))
	C = [[0.0] * n for _ in range(m)]
	for (j, B_j) in enumerate(B):
		C_j = C[j]
		for (k, A_k) in enumerate(A):
			Bkj = B_j[k]
			for (i, Aik) in enumerate(A_k):
				C_j[i] = mod_prod(Aik, Bkj, C_j[i])
	return C

def power(A, B, n, mult_func):
	if n == 0:
		return B
	while n > 1:
		if n % 2 == 1:
			B = mult_func(A, B)
		A = mult_func(A, A)
		n //= 2
	return mult_func(A, B)
