import heapq

class Solution:
    def reachableNodes(self, edges: List[List[int]], maxMoves: int, n: int) -> int:
        graph = [[] for _ in range(n)]
        for u, v, ctr in edges:
            graph[u].append((v, ctr + 1))
            graph[v].append((u, ctr + 1))
        dist = [float('inf')] * n
        dist[0] = 0
        heap = [(0, 0)]
        while heap:
            d, curr = heapq.heappop(heap)
            for j, w in graph[curr]:
                if dist[j] > d + w:
                    dist[j] = d + w
                    heapq.heappush(heap, (dist[j], j))
        res = 0
        for i in range(n):
            if dist[i] <= maxMoves:
                res += 1
        for u, v, ctr in edges:
            left = max(maxMoves - dist[u], 0)
            right = max(maxMoves - dist[v], 0)
            res += min(left + right, ctr)
        return res

from collections import defaultdict
import sys

def solve():
	readline = sys.stdin.readline
	write = sys.stdout.write
	MOD = 10 ** 9 + 7
	(Na, Nt, Ng, Nc) = map(int, readline().split())
	L = Na + Nt + Ng + Nc
	M = int(readline())
	MP = {}
	S = []
	for i in range(M):
		s = readline().strip()
		(s1, s2) = s.split(': ')
		MP[s1] = s2.split(' ')
		S.append(s1)
	R = []
	memo = {}

	def dfs(s):
		if s in memo:
			return memo[s]
		r = []
		for e in MP[s]:
			if e[0] == '[':
				w = 0
				for v in map('ATGC'.index, e[1:-1]):
					w |= 1 << v
				r.append(w)
			else:
				r0 = dfs(e)
				if r0 is None:
					return None
				r.extend(r0)
		if len(r) > L:
			return None
		memo[s] = r
		return r
	res = dfs(S[0])
	if res is None or len(res) < L:
		write('0\n')
		return
	L = len(res)
	T = [defaultdict(int) for i in range(L + 1)]
	T[0][Na, Nt, Ng, Nc] = 1
	for k in range(L):
		s = res[k]
		p0 = s & 1
		p1 = s & 2
		p2 = s & 4
		p3 = s & 8
		T1 = T[k + 1]
		for ((a, b, c, d), v) in T[k].items():
			v %= MOD
			if p0 and a:
				T1[a - 1, b, c, d] += v
			if p1 and b:
				T1[a, b - 1, c, d] += v
			if p2 and c:
				T1[a, b, c - 1, d] += v
			if p3 and d:
				T1[a, b, c, d - 1] += v
	write('%d\n' % (T[L][0, 0, 0, 0] % MOD))
