from collections import Counter

class Solution:
    def gridIllumination(self, n: int, lamps: List[List[int]], queries: List[List[int]]) -> List[int]:
        rowctr = Counter()
        colctr = Counter()
        posdiagctr = Counter()
        negdiagctr = Counter()
        onlamps = set()
        for i, j in lamps:
            if (i, j) not in onlamps:
                rowctr[i] += 1
                colctr[j] += 1
                posdiagctr[i + j] += 1
                negdiagctr[i - j] += 1
                onlamps.add((i, j))
        res = []
        for i, j in queries:
            if rowctr[i] > 0 or colctr[j] > 0 or posdiagctr[i + j] > 0 or negdiagctr[i - j] > 0:
                res.append(1)
            else:
                res.append(0)
            for x in range(i - 1, i + 2):
                for y in range(j - 1, j + 2):
                    if 0 <= x < n and 0 <= y < n and (x, y) in onlamps:
                        onlamps.remove((x, y))
                        rowctr[x] -= 1
                        colctr[y] -= 1
                        posdiagctr[x + y] -= 1
                        negdiagctr[x - y] -= 1
        return res

class Solution:
    def maxValue(self, n: int, index: int, maxSum: int) -> int:
        beg = 1
        end = maxSum
        res = -1
        while beg <= end:
            mid = (beg + end) // 2
            currsum = mid * mid
            left = index - mid + 1
            right = index + mid - 1
            if left < 0:
                x = -left
                currsum -= x * (x + 1) // 2
            else:
                currsum += left
            if right >= n:
                x = right - n + 1
                currsum -= x * (x + 1) // 2
            else:
                currsum += n - right - 1
            if currsum <= maxSum:
                res = mid
                beg = mid + 1
            else:
                end = mid - 1
        return res

class Solution:

	def shoppingOffers(self, price, special, needs):

		def dfs(curr, special, needs):
			p = curr + sum((p * needs[i] for (i, p) in enumerate(price)))
			for si in range(len(special)):
				s = special[si]
				if all((n >= s[i] for (i, n) in enumerate(needs))):
					p = min(p, dfs(curr + s[-1], special[si:], [n - s[i] for (i, n) in enumerate(needs)]))
			return p
		return dfs(0, special, needs)

