def is_balanced(s):
	stack = []
	for c in s:
		if c == '(' or c == '[':
			stack.append(c)
		elif c == ')':
			if not stack:
				return 'no'
			elif stack[-1] == '(':
				stack.pop()
			else:
				return 'no'
		elif c == ']':
			if not stack:
				return 'no'
			elif stack[-1] == '[':
				stack.pop()
			else:
				return 'no'
	if stack:
		return 'no'
	else:
