def solve():
	(P, Q) = getInts()
	if P < Q:
		return P
	if P % Q > 0:
		return P
	facs = sorted(list(factors(Q)))
	best = 0
	for fac in facs:
		if fac == 1:
			continue
		power = 1
		while P % fac ** power == 0:
			tmp = P // fac ** power
			if tmp % Q > 0:
				best = max(best, tmp)
			power += 1
	return best
