class Solution:

	def getMaxArea(self, histogram):
		stack = []
		maxarea = 0
		for (i, h) in enumerate(histogram):
			start = i
			while stack and stack[-1][1] > h:
				(index, height) = stack.pop()
				maxarea = max(maxarea, height * (i - index))
				start = index
			stack.append([start, h])
