def cycle_detectable_topological_sort(graph: List[List[int]], in_degrees: List[int], first_index: int=0) -> Tuple[Optional[List[int]], Optional[List[int]]]:
	V = len(graph) + first_index
	order = []
	depths = [-1] * V
	for i in range(first_index, V):
		if not in_degrees[i]:
			order.append(i)
			depths[i] = 0
	queue = deque(order)
	while queue:
		u = queue.popleft()
		cur_depth = depths[u]
		for v in graph[u]:
			in_degrees[v] -= 1
			if not in_degrees[v]:
				depths[v] = max(depths[v], cur_depth + 1)
				(queue.append(v), order.append(v))
	return (order, depths) if len(order) + first_index == V else (None, None)

