def bestcost(edge, start, fin):
	if not canreach(edge, start, fin, 0):
		return -1
	ans = 0
	forbid = 0
	curbit = 512
	while curbit:
		if canreach(edge, start, fin, forbid | curbit):
			forbid |= curbit
		else:
			ans |= curbit
		curbit >>= 1
	return ans

def canreach(edge, start, fin, forbid):
	seen = [False] * len(edge)
	stack = [start]
	while stack:
		v = stack.pop()
		if v == fin:
			return True
		if not seen[v]:
			seen[v] = True
			stack += [v2 for (v2, cost) in edge[v] if cost & forbid == 0]
	return False
