def Combi(a, b):
	if COMBI[a][b] != -1:
		return COMBI[a][b]
	if 0 <= b <= a:
		COMBI[a][b] = FACT[a] * FACT_INV[b] * FACT_INV[a - b] % mod
		return COMBI[a][b]
	else:
		COMBI[a][b] = 0
		return 0
