def rect(H, W):
	if H == W == 0:
		return 1
	if RA[H][W] != -1:
		return RA[H][W]
	DP = [[[0, 0] for j in range(W + 1)] for i in range(H + 1)]
	DP[0][0][0] = 1
	DP[0][0][1] = 1
	for h in range(H + 1):
