			for nexth in range(h + 1, H + 1):
				DP[nexth][w][0] += DP[h][w][1] * FACT_INV[nexth - h]
				DP[nexth][w][0] %= mod
			for nextw in range(w + 1, W + 1):
				DP[h][nextw][1] += DP[h][w][0] * FACT_INV[nextw - w]
				DP[h][nextw][1] %= mod
