	return min((len({M[x][z] for z in range(N)}) for x in range(N))) == N == min((len({M[z][x] for z in range(N)}) for x in range(N)))

def getIdentity(M):
	for e in range(len(M)):
		for x in range(len(M)):
			if M[e][x] == x == M[x][e]:
				continue
			else:
				break
		else:
			return e
	return None

def isAssociative(M):
	N = len(M)
	for a in range(N):
		for b in range(N):
			for c in range(N):
				if M[a][M[b][c]] != M[M[a][b]][c]:
					return False
	return True

def invertsTo(M, e):
	N = len(M)
	for x in range(N):
		for y in range(N):
			if M[x][y] == M[y][x] == e:
				break
		else:
			return False
	return True

def isCommutative(M):
	for i in range(len(M)):
		for j in range(i + 1, len(M)):
			if M[i][j] != M[j][i]:
				return False
	return True

def autoInversion(M):
	for x in range(len(M)):
		if M[x][x] != x:
			return False
	return True

def isRack(M):
	N = len(M)
	left = min((len({M[x][z] for z in range(N)}) for x in range(N))) == N
	if not left:
		return False
	for a in range(N):
		for b in range(N):
			for c in range(N):
				if M[a][M[b][c]] != M[M[a][b]][M[a][c]]:
					return False
	return True
