def magicNumber(M):
	divides = isDivisible(M)
	identity = getIdentity(M)
	has_identity = identity != None
	inverts = has_identity and invertsTo(M, identity)
	associates = isAssociative(M)
	auto_inverts = autoInversion(M)
	commutes = isCommutative(M)
	quasigroup = divides
	loop = divides and has_identity
	semigroup = associates
	monoid = associates and has_identity
	group = divides and associates and inverts and has_identity
	abelian_group = group and commutes
	rack = isRack(M)
	quandle = rack and auto_inverts
	number = [quasigroup, loop, semigroup, monoid, group, abelian_group, rack, quandle]
	n = 0
	while number:
		n = 2 * n + number.pop()
	return n
