class Solution:

	def zigzagLevelOrder(self, root):
		if root == None:
			return []
		result = []
		queue = []
		queue.append([0, root])
		while len(queue) != 0:
			(level, temp) = queue.pop(0)
			if len(result) < level + 1:
				result.append([])
			if level % 2 == 0:
				result[level].append(temp.val)
			else:
				result[level].insert(0, temp.val)
			if temp.left:
				queue.append([level + 1, temp.left])
			if temp.right:
				queue.append([level + 1, temp.right])
		return result

class Solution:
    def findBottomLeftValue(self, root) -> int:
        res = (-1, 0, 0)
        def inorder(r, d, w):
            nonlocal res
            if not r:
                return
            inorder(r.left, d + 1, 2 * w)
            res = max(res, (d, -w, r.val))
            inorder(r.right, d + 1, 2 * w + 1)
        inorder(root, 0, 0)
        return res[2]

def bipartiteMatch(graph):
	matching = {}
	for u in graph:
		for v in graph[u]:
			if v not in matching:
				matching[v] = u
				break
	while 1:
		preds = {}
		unmatched = []
		pred = dict([(u, unmatched) for u in graph])
		for v in matching:
			del pred[matching[v]]
		layer = list(pred)
		while layer and (not unmatched):
			newLayer = {}
			for u in layer:
				for v in graph[u]:
					if v not in preds:
						newLayer.setdefault(v, []).append(u)
			layer = []
			for v in newLayer:
				preds[v] = newLayer[v]
				if v in matching:
					layer.append(matching[v])
					pred[matching[v]] = v
				else:
					unmatched.append(v)
		if not unmatched:
			unlayered = {}
			for u in graph:
				for v in graph[u]:
					if v not in preds:
						unlayered[v] = None
			return (matching, list(pred), list(unlayered))

		def recurse(v):
			if v in preds:
				L = preds[v]
				del preds[v]
				for u in L:
					if u in pred:
						pu = pred[u]
						del pred[u]
						if pu is unmatched or recurse(pu):
							matching[v] = u
							return 1
			return 0
		for v in unmatched:
			recurse(v)

