class SegTree:

	def __init__(self, init_val, segfunc, ide_ele):
		n = len(init_val)
		self.segfunc = segfunc
		self.ide_ele = ide_ele
		self.num = 1 << (n - 1).bit_length()
		self.tree = [ide_ele] * 2 * self.num
		for i in range(n):
			self.tree[self.num + i] = init_val[i]
		for i in range(self.num - 1, 0, -1):
			self.tree[i] = self.segfunc(self.tree[2 * i], self.tree[2 * i + 1])

	def update(self, k, x):
		k += self.num
		self.tree[k] = x
		while k > 1:
			self.tree[k >> 1] = self.segfunc(self.tree[k], self.tree[k ^ 1])
			k >>= 1

	def query(self, l, r):
		res = self.ide_ele
		l += self.num
		r += self.num
		while l < r:
			if l & 1:
				res = self.segfunc(res, self.tree[l])
				l += 1
			if r & 1:
				res = self.segfunc(res, self.tree[r - 1])
			l >>= 1
			r >>= 1
		return res

class Binary_Indexed_Tree:

	def __init__(self, n):
		self.N = n
		self.BIT = [0] * (n + 1)
		self.l2 = 2 ** (len(format(n, 'b')) - 1)

	def get_sum(self, idx):
		res_sum = 0
		while idx > 0:
			res_sum += self.BIT[idx]
			idx -= idx & -idx
		return res_sum

	def query(self, l, r):
		return self.get_sum(r) - self.get_sum(l - 1)

	def add(self, idx, x):
		while idx <= self.N:
			self.BIT[idx] += x
			idx += idx & -idx
		return

	def lower_bound(self, w):
		if w <= 0:
			return 0
		x = 0
		k = self.l2
		while k > 0:
			if x + k <= self.N and self.BIT[x + k] < w:
				w -= self.BIT[x + k]
				x += k
			k //= 2
		return x + 1

	def upper_bound(self, w):
		x = 0
		k = self.l2
		while k > 0:
			if x + k <= self.N and self.BIT[x + k] <= w:
				w -= self.BIT[x + k]
				x += k
			k //= 2
		return x + 1

class std_map:

	def __init__(self, n, init):
		self.size = n
		self.keys = set()
		self.bit = Binary_Indexed_Tree(n + 1)
		self.dic = [init] * (n + 1)

	def __contains__(self, key):
		return key in self.keys

	def __getitem__(self, key):
		return self.dic[key]

	def __setitem__(self, key, value):
		if not key in self.keys:
			self.bit.add(key, 1)
			self.keys.add(key)
		self.dic[key] = value

	def remove(self, key):
		self.keys.remove(key)
		self.bit.add(key, -1)

	def lower_bound(self, k):
		return self.bit.lower_bound(self.bit.get_sum(k))

	def upper_bound(self, k):
		return self.bit.upper_bound(self.bit.get_sum(k))

	def kth_key(self, k):
		return self.bit.lower_bound(k)

	def kth_value(self, k):
		return self.dic[self.kth_key(k)]

	def prev_k(self, k):
		idx = self.bit.get_sum(k)
		if idx == 0:
			return -1
		return self.bit.lower_bound(idx - 1)

	def prev_k(self, k):
		idx = self.bit.get_sum(k)
		if idx == self.size:
			return -1
		return self.bit.lower_bound(idx + 1)

