def most_common_words(text):
    words = text.split()
    word_frequency = {}
    for word in words:
        if word in word_frequency:
            word_frequency[word] += 1
        else:
            word_frequency[word] = 1
    max_value = 0
    most_common = None
    for word in word_frequency:
        if word_frequency[word] > max_value:
            max_value = word_frequency[word]
            most_common = word
    return most_common
