def countPrimeNumber(n):
	count = 0
	while n % 2 == 0:
		n = n / 2
		count += 1
	i = 3
	while i <= n ** 0.5:
		while n % i == 0:
			n /= i
			count += 1
		i += 2
	if n > 2:
		count += 1
	return count

def printKAlmostPrimes(k, n):
	i = 1
	num = 2
	while i <= n:
		if countPrimeNumber(num) == k:
			print(num, end='')
			print(' ', end='')
			i += 1
		num += 1

