def createks(k):
	ks = ['a', 'a']
	if k == 1:
		return ks
	ks = ['a', 'a', 'b', 'b', 'a']
	if k == 2:
		return ks
	msd = 2
	while msd < k:
		ks.extend([chr(ord('a') + msd), chr(ord('a') + msd - 1), chr(ord('a') + msd)])
		for i in range(msd - 1):
			ks.extend(chr(ord('a') + msd))
			ks.extend(chr(ord('a') + (msd - (2 + i))))
		msd += 1
	return ks

def answer(n, k):
	ks = createks(k)
	ans = []
	extra = n - len(ks)
	for i in range(min(n, len(ks))):
		ans.append(ks[i])
	ks.pop(0)
	for i in range(extra):
		ans.append(ks[i % len(ks)])
	return ''.join(ans)

