class Solution:

	def distance(self, x1, x2, y1, y2):
		x_diff = (x1 - x2) * (x1 - x2)
		y_diff = (y1 - y2) * (y1 - y2)
		return sqrt(x_diff + y_diff)

	def compute(self, x, line, n, points):
		(a, b, c) = line
		y = -(a * x + c) / b
		res = 0.0
		for (x1, y1) in points:
			res += self.distance(x, x1, y, y1)
		return res

	def findOptimumCost(self, line: List[int], n: int, points: List[List[int]]) -> float:
		low = -1000
		high = 1000
		eps = 0.001
		if line[1] == 0:
			return float('inf')
		while high - low > eps:
			mid1 = low + (high - low) / 3
			mid2 = high - (high - low) / 3
			dist1 = self.compute(mid1, line, n, points)
			dist2 = self.compute(mid2, line, n, points)
			if dist1 < dist2:
				high = mid2
			else:
				low = mid1
		avg = (low + high) / 2
		return self.compute(avg, line, n, points)

