class Solution:

	def xor_play(self, n):
		if n == 1:
			return [0]
		result = [1]
		i = 2
		while i * i <= n:
			if n % i == 0:
				result.append(i)
				if i != n // i:
					result.append(n // i)
			i += 1
		result.sort()
		xor_result = 0
		for d in result:
			xor_result ^= d
		result.append(xor_result)
