def solve(s):
	n = len(s)
	index = make_index(s)
	odd = None
	for (code, char_pos) in enumerate(index):
		if len(char_pos) % 2 == 1:
			if odd is not None:
				return -1
			odd = code
	bit = Bit(n)
	ans = 0
	cnt = 0
	for i in range(n):
		if bit.sum(i + 1) - bit.sum(i) == 1:
			continue
		code = ord(s[i]) - a
		if code == odd and index[code][-1] == i:
			continue
		cnt += 1
		j = index[code].pop()
		ans += n - cnt - (j - bit.sum(j))
		bit.add(j, 1)
		if n // 2 <= cnt:
			break
	if odd is not None:
		j = index[odd][-1]
		ans += abs(n // 2 - (j - bit.sum(j)))
	return ans

