import math
import itertools
pow10 = [1]
for i in range(10):
	pow10.append(pow10[-1] * 10)

def getlen(x):
	return int(math.log10(x)) + 1

class ShortestRepresentation:

	def __init__(self, n):
		self.n = n
		self._m = {}
		self._s = [set() for i in range(10)]
		self._generate_powers()
		self._generate_power_and_power(7)
		self._generate_simple_and_power(7)

	def _generate_powers(self):
		range_x = itertools.takewhile(lambda x: x ** 2 <= self.n, itertools.count(2))
		for x in range_x:
			c = x ** 2
			p = 2
			while c <= self.n:
				self.update(c, '{}^{}'.format(x, p))
				c *= x
				p += 1

	def _generate_power_and_power(self, maxlen):
		for i in range(1, maxlen + 1):
			range_j = itertools.takewhile(lambda j: i + j + 1 <= maxlen, itertools.count(i))
			for j in range_j:
				for (x, y) in itertools.product(self._s[i], self._s[j]):
					x2 = self.get(x)
					y2 = self.get(y)
					self.update(x * y, '{}*{}'.format(x2, y2))

	def _generate_simple_and_power(self, maxlen):
		for i in range(1, maxlen - 1):
			range_xy = itertools.product(range(1, pow10[maxlen - 1 - i]), self._s[i])
			for (x, y) in range_xy:
				y2 = self.get(y)
				self.update(x * y, '{}*{}'.format(x, y2))

	def update(self, x, s):
		if x > self.n:
			return
		ls = len(s)
		if ls >= getlen(x):
			return
		if x not in self._m:
			self._m[x] = s
			self._s[ls].add(x)
		else:
			lm = len(self._m[x])
			if ls < lm:
				self._s[lm].remove(x)
				self._m[x] = s
				self._s[ls].add(x)

	def get(self, x):
		return self._m[x] if x in self._m else str(x)
n = int(input())
if n < 10 ** 10:
	sr = ShortestRepresentation(n)
	ans = sr.get(n)
	range_i = itertools.takewhile(lambda i: i * 2 + 1 < len(ans), itertools.count())
	for i in range_i:
		range_x = itertools.chain(range(1, pow10[i] + 1), sr._s[i])
		for x in range_x:
			ans = min(ans, '{}+{}'.format(sr.get(x), sr.get(n - x)), key=len)
			if n % x > 0:
				continue
			ans = min(ans, '{}*{}'.format(sr.get(x), sr.get(n // x)), key=len)
	print(ans)
else:
