import math

class Solution:
    def isPrime(self, n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(math.sqrt(n)) + 1, 2):
            if n % i == 0:
                return False
        return True

    def factorial(self, n):
        if n <= 1:
            return 1
        return n * self.factorial(n - 1)

    def numPrimeArrangements(self, n: int) -> int:
        numPrimes = 0
        for i in range(1, n + 1):
            if self.isPrime(i):
                numPrimes += 1
        return (self.factorial(numPrimes) * self.factorial(n - numPrimes)) % (10 ** 9 + 7)

import heapq

class Solution:

	def minTime(self, dependency, duration, n, m):
		degree = [0] * n
		adj = [[] for _ in range(n)]
		for edge in dependency:
			adj[edge[0]].append(edge[1])
			degree[edge[1]] += 1
		dist = [-1] * n
		pq = []
		for i in range(n):
			if degree[i] == 0:
				dist[i] = duration[i]
				heapq.heappush(pq, (dist[i], i))
		while len(pq) > 0:
			(d, v) = heapq.heappop(pq)
			for w in adj[v]:
				degree[w] -= 1
				if degree[w] == 0:
					dist[w] = d + duration[w]
					heapq.heappush(pq, (dist[w], w))
		if -1 in dist:
			return -1
		return max(dist)

